create table if not exists public.notifications (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,body text,type text not null default 'general',read_at timestamptz,created_at timestamptz not null default now());
alter table public.notifications enable row level security;
create policy "Users read own notifications" on public.notifications for select to authenticated using((select auth.uid())=user_id);
create policy "Users mark own notifications read" on public.notifications for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create index if not exists notifications_user_created_idx on public.notifications(user_id,created_at desc);
create table if not exists public.faqs (id uuid primary key default gen_random_uuid(),question text not null,answer text not null,category text not null default 'general',status text not null default 'draft' check(status in ('draft','published','archived')),created_at timestamptz not null default now());
alter table public.faqs enable row level security;
create policy "Published FAQs are public" on public.faqs for select to anon,authenticated using(status='published');
create table if not exists public.grievances (id uuid primary key default gen_random_uuid(),ticket_code text unique not null,requester_id uuid references auth.users(id) on delete set null,anonymous boolean not null default false,title text not null,description text not null,category text not null default 'general',status text not null default 'submitted' check(status in ('submitted','under_review','actioned','resolved','closed')),assigned_to uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.grievances enable row level security;
create policy "Users read own grievances" on public.grievances for select to authenticated using((select auth.uid())=requester_id and anonymous=false);
create policy "Users create grievances" on public.grievances for insert to authenticated with check((select auth.uid())=requester_id);
create index if not exists grievances_status_idx on public.grievances(status,created_at desc);
create table if not exists public.grievance_updates (id uuid primary key default gen_random_uuid(),grievance_id uuid not null references public.grievances(id) on delete cascade,status text not null,note text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
alter table public.grievance_updates enable row level security;
create policy "Users read updates on own grievances" on public.grievance_updates for select to authenticated using(exists(select 1 from public.grievances g where g.id=grievance_id and g.requester_id=(select auth.uid()) and g.anonymous=false));
create table if not exists public.issues (id uuid primary key default gen_random_uuid(),title text not null,description text not null,category text not null default 'general',status text not null default 'open' check(status in ('open','acknowledged','in_progress','resolved','closed')),anonymous boolean not null default true,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
alter table public.issues enable row level security;
create policy "Public issues are visible when moderated" on public.issues for select to anon,authenticated using(status in ('acknowledged','in_progress','resolved','closed'));
create policy "Authenticated users can submit issues" on public.issues for insert to authenticated with check((select auth.uid())=created_by);
create table if not exists public.issue_votes (issue_id uuid not null references public.issues(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(issue_id,user_id));
alter table public.issue_votes enable row level security;
create policy "Users manage own issue votes" on public.issue_votes for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create table if not exists public.interventions (id uuid primary key default gen_random_uuid(),issue_id uuid references public.issues(id) on delete set null,action text not null,outcome text,status text not null default 'planned' check(status in ('planned','in_progress','completed')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
alter table public.interventions enable row level security;
create policy "Completed interventions are public" on public.interventions for select to anon,authenticated using(status='completed');